import {
  Icon,
  IconElement,
  IndexPath,
  Menu,
  MenuGroup,
  MenuItem,
  Spinner,
} from '@ui-kitten/components';
import {useCallback, useEffect, useState} from 'react';
import {KEY_TASK} from '../../helper';
import {useBoardService} from '../../../../../hooks/apiHooks/useAPI';
import useBoardStore from '../../store';
import {useAppSelector} from '../../../../../hooks/useRedux';
import {ITask} from '../../store/interface';
import TextCM from '../../../../components/Text';
import {Pressable} from 'react-native';
import BottomSheetCM from '../../../../components/BottomSheet';
import ListActionScreen from './components/action-task';
import {useNavigation, useRoute} from '@react-navigation/native';
import {NavigationName} from '../../../../../constants';

const BrowserIcon = (props: any): IconElement => (
  <Icon {...props} name="browser-outline" />
);

const StarIcon = (props: any): IconElement => (
  <Icon {...props} name="file-text-outline" />
);

type Props = {
  refreshing: boolean;
  setRefreshing: (value: boolean) => void;
};

const ListTask = ({refreshing, setRefreshing}: Props) => {
  const navigation = useNavigation<any>();
  const [selectedIndex, setSelectedIndex] = useState<IndexPath | undefined>(
    undefined,
  );
  const [isInitData, setIsInitData] = useState<'loading' | 'error' | 'success'>(
    'loading',
  );
  const [isShowAction, setIsShowAction] = useState(false);
  const [taskSelect, setTaskSelect] = useState<ITask>();
  const {
    addListHeaderTaskByKey,
    getListHeaderTask,
    listHeaderTask,
    setGroupTaskList,
    setListTaskIdSelect,
  } = useBoardStore();
  const BoardServices = useBoardService();
  const {dataAccount} = useAppSelector(state => state.account);

  useEffect(() => {
    // BoardServices.login();
    initData();
  }, []);

  useEffect(() => {
    if (refreshing) {
      initData();
    }
  }, [refreshing]);

  const initData = async () => {
    try {
      setIsInitData('loading');
      await Promise.all([
        getListTaskOfMine(),
        getListTaskAll(),
        getGroupUserBelong(),
        getListTaskApproved(),
        getListTaskInProgress(),
        getMyTemplate(),
        getCoordinatorTask(),
      ]);
      setIsInitData('success');
    } catch (error) {
      setIsInitData('error');
    } finally {
      setRefreshing(false);
    }
  };

  const getListTaskOfMine = async () => {
    try {
      const body = {
        createdBy: dataAccount.email || 'binhntt6@fpt.com.vn',
      };
      const params = {
        page: 0,
        size: 1000000,
        sort: 'createdDate,desc',
      };
      const data = (await BoardServices.getListTaskOfMine(body, params)) as any;
      if (data && data?.data.length > 0) {
        addListHeaderTaskByKey(data.data, KEY_TASK['my-task']);
      }
      return data;
    } catch (error) {}
  };

  const getListTaskInProgress = async () => {
    try {
      const body = {};
      const params = {
        page: 0,
        size: 1000000,
        sort: 'createdDate,desc',
      };
      const data = (await BoardServices.searchProcessListTask(
        body,
        params,
      )) as any;
      if (data && data?.data.length > 0) {
        addListHeaderTaskByKey(data.data, KEY_TASK['in-progress-task']);
      }
    } catch (error) {}
  };

  const getListTaskAll = async () => {
    try {
      const body = {
        assignOrgList: [dataAccount.orgIn || '/7/1'],
        privateLt: false,
      };
      const params = {
        sort: 'createdDate,desc',
      };
      const data = (await BoardServices.getListTaskAll(body, params)) as any;
      if (data && data?.data.length > 0) {
        addListHeaderTaskByKey(data.data, KEY_TASK['assigned-task']);
      }
      return data;
    } catch (error) {}
  };

  const getListTaskApproved = async () => {
    try {
      const data = await BoardServices.getListTaskApproved();
      addListHeaderTaskByKey(data, KEY_TASK['pending-task']);
    } catch (error) {}
  };

  const getCoordinatorTask = async () => {
    try {
      const body = {
        coordinator: true,
      };
      const params = {
        page: 0,
        size: 1000000,
        sort: 'createdDate,desc',
      };
      const data = await BoardServices.searchListTask(body, params);
      if (data) {
        addListHeaderTaskByKey(data?.data, KEY_TASK['coordinator-task']);
      }
    } catch (error) {}
  };

  const getGroupUserBelong = async () => {
    try {
      const data = await BoardServices.getGroupUserBelong(dataAccount.id || 11);
      // setGroupUserBelong(data);
      const groupUserIdSharedList = data?.map((group: any) => group.id);
      getPersmissionTemplate(groupUserIdSharedList);
      getPermissionTask(groupUserIdSharedList);
    } catch (error) {}
  };

  const getPermissionTask = async (groupUserIdSharedList: number[]) => {
    try {
      const body = {
        userIdShared: (dataAccount.id as number) || 11,
        groupUserIdSharedList: groupUserIdSharedList,
        privateLt: false,
      };
      const params = {
        page: 0,
        size: 1000000,
        sort: 'createdDate,desc',
      };
      const data = await BoardServices.searchListTask(body, params);
      if (data) {
        const userIdAndGroupUserIdList = data?.data.map((r: any) => {
          return {
            userId: dataAccount.id || 11,
            groupUserIdList: groupUserIdSharedList,
            type: 'L' as 'L' | 'T',
            resourceId: r.id,
          };
        });
        const respACL = await BoardServices.getAclByUserIdAndGroupUserId({
          userIdAndGroupUserIdList,
        });
        if (respACL) {
          const filterData = data?.data?.map((task: ITask, index: number) => ({
            ...task,
            acls: [respACL[index]?.id],
          }));
          addListHeaderTaskByKey(filterData, KEY_TASK['permission-task']);
        }
      }
    } catch (error) {}
  };

  const getPersmissionTemplate = async (groupUserIdSharedList: number[]) => {
    try {
      const body = {
        userIdShared: (dataAccount.id as number) || 11,
        groupUserIdSharedList: groupUserIdSharedList,
        q: '',
      };
      const params = {
        page: 0,
        size: 1000000,
        sort: 'createdDate,desc',
      };
      const data = await BoardServices.getTemplateListTask(body, params);
      if (data) {
        const userIdAndGroupUserIdList = data?.data.map((r: any) => {
          return {
            userId: dataAccount.id || 11,
            groupUserIdList: groupUserIdSharedList,
            type: 'L' as 'L' | 'T',
            resourceId: r.id,
          };
        });
        const respACL = await BoardServices.getAclByUserIdAndGroupUserId({
          userIdAndGroupUserIdList,
        });
        if (respACL) {
          const filterData = data?.data?.map((task: ITask, index: number) => ({
            ...task,
            acls: [respACL[index]?.id],
          }));
          addListHeaderTaskByKey(
            filterData,
            KEY_TASK['template-permission-task'],
          );
        }
      }
    } catch (error) {}
  };

  const getMyTemplate = async () => {
    try {
      const body = {
        createdBy: dataAccount.email || 'binhntt6@fpt.com.vn',
        q: '',
      };
      const params = {
        page: 0,
        size: 1000000,
        sort: 'createdDate,desc',
      };
      const data = await BoardServices.getTemplateListTask(body, params);
      if (data) {
        addListHeaderTaskByKey(data?.data, KEY_TASK['template-task']);
      }
    } catch (error) {}
  };

  const handleSelectTaskItem = (task: ITask) => {
    setTaskSelect(task);
    setListTaskIdSelect(task.id);
    navigation.navigate(NavigationName.TaskScreen, {
      taskId: task.id,
    });
  };

  return (
    <>
      <Menu
        scrollEnabled={false}
        selectedIndex={selectedIndex}
        onSelect={index => {
          setSelectedIndex(index);
        }}>
        {isInitData === 'success' ? (
          getListHeaderTask().map((item, index) => (
            <MenuGroup
              key={`${item.key}-${item.child?.length}`} // Thêm số lượng child vào key
              title={item.name}
              accessoryLeft={BrowserIcon}>
              {item.child?.map(task => (
                <MenuItem
                  onPress={() => handleSelectTaskItem(task)}
                  key={task.id}
                  title={task.name}
                  accessoryLeft={StarIcon}
                  accessoryRight={
                    <Pressable
                      onPress={() => {
                        setIsShowAction(true);
                        setTaskSelect(task);
                      }}>
                      <Icon name="more-horizontal-outline" />
                    </Pressable>
                  }
                />
              ))}
            </MenuGroup>
          ))
        ) : isInitData === 'error' ? (
          <TextCM>Có lỗi xảy ra</TextCM>
        ) : (
          <Spinner />
        )}
      </Menu>

      <BottomSheetCM
        title={'Action'}
        isVisible={isShowAction}
        onClose={() => setIsShowAction(false)}
        renderContent={
          <ListActionScreen
            taskSelect={taskSelect}
            onClose={() => setIsShowAction(false)}
            keyTask={listHeaderTask?.[selectedIndex?.row as number]?.key}
          />
        }
      />
    </>
  );
};

export default ListTask;
