import {
  View,
  Text,
  TouchableOpacity,
  ScrollView,
  useWindowDimensions,
} from 'react-native';
import Animated, {FadeInUp} from 'react-native-reanimated';
import {styles} from './styles';
import ModalFullScreen from '../../../components/ModalFullScreen';
import {useState} from 'react';
import HeaderCM from '../../../components/Header/HeaderCM';
import {Color} from '../../../../constants';
import DashboardTaskList from '../DashboardTaskList';
import {TaskGroup} from '../../../../model/interface/dashboard.interface';
import {useTranslation} from 'react-i18next';
import {Tab, TabView} from '@ui-kitten/components';

interface StatCardProps {
  title: string;
  count: number;
  delay?: number;
  isHalfWidth?: boolean;
}

type Props = {
  taskCount: {
    [key: string]: number;
    missedCount: number;
    processingCount: number;
    totalCount: number;
  };
  taskCompleted?: TaskGroup[];
  taskLated?: TaskGroup[];
};
export default function DashboardDetail({
  taskCount,
  taskCompleted,
  taskLated,
}: Props) {
  const {t} = useTranslation();
  const {width} = useWindowDimensions();
  const [isShowCountTask, setIsShowCountTask] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(0);

  const StatCard = ({
    title,
    count,
    delay = 0,
    isHalfWidth = false,
  }: StatCardProps) => {
    return (
      <Animated.View
        entering={FadeInUp.delay(delay)}
        style={[styles.card, isHalfWidth && {width: (width - 16 * 3) / 2}]}>
        <TouchableOpacity onPress={() => setIsShowCountTask(true)}>
          <Text style={styles.title}>{title}</Text>
          <Text style={styles.count}>{count}</Text>
          <Text style={styles.subtitle}>{'Công việc'}</Text>
        </TouchableOpacity>
      </Animated.View>
    );
  };

  return (
    <View style={styles.container}>
      <View style={styles.topRow}>
        <StatCard
          title={t('HM.missedCount')}
          count={taskCount.missedCount}
          delay={100}
          isHalfWidth={true}
        />
        <StatCard
          title={t('HM.processingCount')}
          count={taskCount.processingCount}
          delay={200}
          isHalfWidth={true}
        />
      </View>
      <StatCard
        title={t('HM.totalCount')}
        count={taskCount.totalCount}
        delay={300}
      />
      <ModalFullScreen
        isVisible={isShowCountTask}
        backdropStyle={{backgroundColor: Color.BgPrimary}}
        paddingBottom={false}
        children={
          <>
            <HeaderCM
              title={'Danh sách task'}
              onPressIconLeft={() => setIsShowCountTask(false)}
              style={{backgroundColor: Color.BgPrimary}}
            />
            <ScrollView style={{flex: 1, backgroundColor: '#fff'}}>
              <TabView
                selectedIndex={selectedIndex}
                onSelect={setSelectedIndex}
                style={{backgroundColor: Color.White}}
                tabBarStyle={{
                  backgroundColor: Color.White,
                  padding: 5,
                  height: 50,
                }}
                indicatorStyle={{backgroundColor: '#3366FF'}}>
                <Tab
                  title={evaProps => (
                    <Text
                      {...evaProps}
                      style={[
                        styles.tabTitle,
                        {color: selectedIndex === 0 ? '#3366FF' : '#8F9BB3'},
                      ]}>
                      {'Task hoàn thành'}
                    </Text>
                  )}>
                  <DashboardTaskList
                    listTask={taskCompleted}
                    type={'complete'}
                  />
                </Tab>
                <Tab
                  title={evaProps => (
                    <Text
                      {...evaProps}
                      style={[
                        styles.tabTitle,
                        {color: selectedIndex === 1 ? '#3366FF' : '#8F9BB3'},
                      ]}>
                      {'Task trễ hạn'}
                    </Text>
                  )}>
                  <DashboardTaskList listTask={taskLated} type={'lated'} />
                </Tab>
              </TabView>
            </ScrollView>
          </>
        }
      />
    </View>
  );
}
