import {Pressable, ScrollView, View} from 'react-native';
import HeaderCM from '../../../../../../components/Header/HeaderCM';
import {useState} from 'react';
import {
  CalendarRange,
  Divider,
  IndexPath,
  RangeDatepicker,
} from '@ui-kitten/components';
import {isEmpty} from 'lodash';
import ButtonCM from '../../../../../../components/Button';
import DropdownListCM from '../../../../../../components/DropDownList';
import TextCM from '../../../../../../components/Text';
import InputCM from '../../../../../../components/TextField/InputCM';
import {PRIORITIES} from '../../../../../board/components/create-new-task/helper';
import styles from './styles';

type Props = {
  onClose: () => void;
  handleSubmitData: (data: any) => void;
};

const AddSubTask = ({onClose, handleSubmitData}: Props) => {
  const [priorityIndex, setPriorityIndex] = useState<IndexPath | undefined>(
    undefined,
  );
  const [range, setRange] = useState<CalendarRange<Date>>({
    startDate: new Date(),
  });
  const [dataName, setDataName] = useState<string>('');
  const [errorName, setErrorName] = useState('');

  const handleChangeValue = (value: string) => {
    setDataName(value);
    if (!value) {
      setErrorName('Không được trống');
    } else {
      setErrorName('');
    }
  };

  const handleSubmit = async () => {
    if (!dataName) {
      setErrorName('Không được trống');
      return;
    }
    const dataUpdate = {
      name: dataName,
      startDate: range.startDate,
      endDate: range.endDate,
      priority: PRIORITIES?.[priorityIndex?.row as any]?.value || null,
    };
    handleSubmitData(dataUpdate);
    onClose();
  };
  return (
    <>
      <HeaderCM
        style={{
          backgroundColor: '#fff',
        }}
        contentStyle={{
          backgroundColor: '#fff',
        }}
        titleStyle={{
          color: '#000810',
        }}
        fillIconBackLeft="#000810"
        onPressIconLeft={() => {
          onClose?.();
        }}
        title="Thêm công việc"
        alignment="start"
      />
      <Divider />

      <ScrollView
        contentContainerStyle={{rowGap: 10}}
        style={{flex: 1, padding: 16}}>
        <InputCM
          isRequired
          label={'Tên công việc'}
          placeholder="Nhập tên công việc"
          value={dataName}
          onChangeText={text => handleChangeValue(text)}
          captionText={errorName}
        />

        <TextCM>{'Ngày thực hiện'}</TextCM>
        <RangeDatepicker
          range={range}
          size="medium"
          controlStyle={styles.calender}
          onSelect={nextRange => setRange(nextRange)}
          min={new Date(1900, 0, 0)}
          placeholder={props => (
            <TextCM {...props}>{'Từ ngày đến ngày'}</TextCM>
          )}
        />
        <DropdownListCM
          label={'Độ ưu tiên'}
          placeholder="Chọn độ ưu tiên"
          size="medium"
          valueSelect={priorityIndex}
          onSelect={setPriorityIndex}
          listData={PRIORITIES}
        />
      </ScrollView>

      <View style={styles.ctnFooter}>
        <ButtonCM style={{flex: 1}} onPress={onClose} label="Quay lại" />
        <ButtonCM
          disabled={isEmpty(errorName) ? false : true}
          style={{flex: 1}}
          onPress={handleSubmit}
          label="Lưu"
        />
      </View>
    </>
  );
};

export default AddSubTask;
