import {useRef, useState} from 'react';
import {TextInput} from 'react-native';
import {Color, Font} from '../../../../../../../constants';

type Props = {
  checkListValueName?: string;
  handleChangeValueCheckList: (value: string, index: number) => void;
  handleFocus: any;
  index: number;
};

const InputValueItem = ({
  checkListValueName,
  handleChangeValueCheckList,
  handleFocus,
  index,
}: Props) => {
  const [checkListValue, setCheckListValue] = useState(checkListValueName);
  const refInput = useRef<TextInput>(null);
  return (
    <TextInput
      style={{
        paddingHorizontal: 10,
        paddingVertical: 10,
        flex: 1,
        color: Color.Text,
        fontFamily: Font.InterRegular400,
      }}
      multiline
      ref={refInput}
      onFocus={() => handleFocus(refInput)}
      value={checkListValue}
      onChangeText={setCheckListValue}
      onBlur={e => handleChangeValueCheckList(e.nativeEvent.text, index)}
    />
  );
};

export default InputValueItem;
