import {useMemo} from 'react';
import styles from './styles';
import {Image, View} from 'react-native';
import {
  AssignGroupList,
  AssignOrgList,
  AssignTaskList,
} from '../task-detail-item/helper';
import {String} from '../../../../../constants';
import TextCM from '../../../../components/Text';
import {useUserStore} from '../../../../../zutand/user-store';
import {Icon} from '@ui-kitten/components';

type Props = {
  assignTaskList: AssignTaskList[] | undefined;
  assignGroupList: AssignGroupList[] | undefined;
  assignOrgList: AssignOrgList[] | undefined;
};

const RenderListUserAssign = ({
  assignTaskList,
  assignGroupList,
  assignOrgList,
}: Props) => {
  const {listUser} = useUserStore();

  const totalAssign = useMemo(() => {
    if (assignTaskList && assignGroupList && assignOrgList) {
      return (
        assignTaskList?.length + assignGroupList?.length + assignOrgList?.length
      );
    }
  }, [assignTaskList?.length, assignGroupList?.length, assignOrgList?.length]);

  const listAssign = useMemo(() => {
    if (assignTaskList && assignGroupList && assignOrgList) {
      return [
        ...assignTaskList.map(userTask => ({
          avt:
            listUser?.find(user => user.resourceId === userTask.userId)
              ?.imageUrl || String.DEFAULT_IMAGE,
          type: `user-${userTask.userId}`,
        })),
        ...assignGroupList.map(userGroup => ({
          avt: 'people',
          type: `group-${userGroup.groupId}`,
        })),
        ...assignOrgList.map(userOrg => ({
          avt: 'people',
          type: `org-${userOrg.orgIn}`,
        })),
      ];
    }
  }, [assignTaskList?.length, assignGroupList?.length, assignOrgList?.length]);

  return (
    <View style={styles.ctnListTaskAssign}>
      {listAssign?.map((item, index) => {
        if (index < 2) {
          return (
            <View
              key={index}
              style={{
                ...styles.ctnViewAvt,
                right: index * 16,
              }}>
              {item.type.startsWith('user') ? (
                <Image
                  style={styles.ctnImg}
                  source={{
                    uri: item.avt,
                  }}
                />
              ) : (
                <View style={styles.ctnIcon}>
                  <Icon fill={'#fff'} name="people" width={16} height={16} />
                </View>
              )}
            </View>
          );
        }
      })}

      {totalAssign && totalAssign > 2 && (
        <View style={styles.ctnAddAvt}>
          <TextCM style={styles.textAdd}>+{totalAssign - 2}</TextCM>
        </View>
      )}
    </View>
  );
};

export default RenderListUserAssign;
